def _get_lock(self) -> asyncio.Lock:
    """Thread-safe lazy init pro asyncio.Lock — DCLP protected by threading.Lock."""
    lock = self._lock
    if lock is None:
        with self._thread_lock:
            lock = self._lock
            if lock is None:
                lock = asyncio.Lock()
                self._lock = lock
    return lock

