def _lock(self) -> asyncio.Lock:
    """Thread-safe lazy init pro asyncio.Lock — double-checked locking chráněný threading.Lock."""
    lock = self.__lock
    if lock is None:
        with self._lock_factory:
            lock = self.__lock
            if lock is None:
                lock = asyncio.Lock()
                self.__lock = lock
    return lock

class _MLXPool:
    """
    MLX compute stream pool (single stream, lazy initialization).
    """
    __slots__ = tuple(('_loaded', '_lock', '_stream'))

    def __init__(self) -> None:
        self._stream: Any | None = None
        self._lock = threading.Lock()
        self._loaded = False

    def acquire(self) -> Any | None:
        """Acquire MLX stream (lazy init)."""
        with self._lock:
            if not self._loaded:
                try:
                    import mlx.core as mx
                    self._stream = mx
                    self._loaded = True
                except ImportError:
                    return None
            return self._stream

    def release(self, _stream: Any) -> None:
        """MLX has single stream, release is no-op."""
        pass

    @property
    def is_available(self) -> bool:
        """Check if MLX is available."""
        try:
            import mlx.core
            return True
        except ImportError:
            return False

