def stage_diagnose(
    self,
    entries_seen: int,
    entries_with_empty_assembled_text: int,
    entries_scanned: int,
    entries_with_hits: int,
    findings_built_pre_store: int,
    patterns_configured: int,
    findings_lost_to_dedup_total: int,
) -> str:
    if patterns_configured == 0:
        return "empty_registry"
    if entries_seen == 0:
        return "empty_fetch"
    if entries_with_empty_assembled_text > 0 and entries_scanned == 0:
        return "content_empty"
    if entries_scanned == 0:
        return "no_pattern_hits"
    if findings_built_pre_store == 0 and findings_lost_to_dedup_total > 0:
        return "findings_build_loss"
    if entries_with_hits == 0:
        return "no_pattern_hits_with_content"
    if findings_built_pre_store > 0:
        return "prestore_findings_present"
    return "unknown"

def branch_hint(
    self,
    feed_signal_present: bool,
    fallback_useful: int,
    fallback_waste: int,
    _findings_rich: int,
    _findings_fallback: int,
    entries_with_hits: int,
) -> str:
    if entries_with_hits == 0:
        return "unknown"
    if feed_signal_present and fallback_waste == 0:
        return "feed_strong"
    if feed_signal_present and fallback_waste > 0 and fallback_useful == 0:
        return "feed_weak"
    if fallback_useful > 0 and _findings_fallback > 0:
        return "fallback_valuable"
    if feed_signal_present or fallback_useful > 0:
        return "mixed"
    return "unknown"

def _python_compress_page(data: bytes, algorithm: str = "lz4") -> bytes:
    """Python fallback: LZ4 compression."""
    if algorithm != "lz4":
        return data
    try:
        import lz4.block

        return lz4.block.compress(data, store_size=False)
    except ImportError:
        # Ultimate fallback: return uncompressed
        return data

def _python_decompress_page(data: bytes, algorithm: str = "lz4") -> bytes:
    """Python fallback: LZ4 decompression."""
    if algorithm != "lz4":
        return data
    try:
        import lz4.block

        return lz4.block.decompress(data)
    except ImportError:
        # Ultimate fallback: return as-is
        return data

class _RustHtmlDomain:
    """Rust-backed HTML parsing via lol_html (Cloudflare's zero-allocation rewriter).
    Bounded: 2MB max HTML size, 10K links per doc, fail-safe on any error.
    Thread-safe: all extractors are Send+Sync.
    """

    __slots__ = ("_ext",)

    def __init__(self, ext: object) -> None:
        self._ext = ext

    def extract_links(self, html: str, base_url: str) -> list[str]:
        """Extract all links (href) resolved against base_url."""
        return self._ext.extract_links(html, base_url)

    def extract_links_with_text(self, html: str, base_url: str) -> list[tuple[str, str]]:
        """Extract links with anchor text."""
        return self._ext.extract_links_with_text(html, base_url)

    def extract_emails(self, html: str) -> list[str]:
        """Extract email addresses from HTML."""
        return self._ext.extract_emails(html)

    def extract_titles(self, html: str) -> list[str | None]:
        """Extract <title> content."""
        title = self._ext.extract_title(html)
        return [title] if title is not None else []

    def html_to_text(self, html: str) -> str:
        """Extract plain text from HTML."""
        return getattr(self._ext, "html_to_text", lambda x: x)(html)

    def batch_extract_links(self, items: list[tuple[str, str]]) -> list[list[str]]:
        """Parallel link extraction for (html, base_url) pairs."""
        return self._ext.batch_extract_links(items)

    def batch_extract_links_with_text(self, items: list[tuple[str, str]]) -> list[list[tuple[str, str]]]:
        """Parallel link+text extraction."""
        return self._ext.batch_extract_links_with_text(items)

    def batch_extract_emails(self, items: list[str]) -> list[list[str]]:
        """Parallel email extraction."""
        return self._ext.batch_extract_emails(items)

    def batch_extract_titles(self, items: list[str]) -> list[str | None]:
        """Parallel title extraction."""
        return self._ext.batch_extract_titles(items)

    def html_extract(self, html: str) -> dict[str, Any]:
        """Extract links, emails, and title from HTML in one call."""
        links = self.extract_links(html, "")
        emails = self.extract_emails(html)
        titles = self.extract_titles(html)
        return {
            "links": links,
            "emails": emails,
            "title": titles[0] if titles else None,
        }

